local _d = ""
local _k = 90
local _b = {}
for i = 1, #_d do
    local c = _d:byte(i)
    _b[i] = string.char(bit32 and bit32.bxor(c, _k) or (c ~ _k))
end
local _src = table.concat(_b)
local _f = loadstring or load
local _fn, _err = _f(_src)
if not _fn then error("Decode error: " .. tostring(_err)) end
return _fn()
